CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, department_name VARCHAR(50) NOT NULL UNIQUE, status TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'admin', status TINYINT NOT NULL DEFAULT 1, session_version INT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS meal_types (id INT AUTO_INCREMENT PRIMARY KEY, meal_name VARCHAR(40) NOT NULL UNIQUE, start_time TIME NOT NULL, end_time TIME NOT NULL, end_inclusive TINYINT NOT NULL DEFAULT 0, status TINYINT NOT NULL DEFAULT 1, display_order INT NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO meal_types(id,meal_name,start_time,end_time,end_inclusive,status,display_order) VALUES (1,'Breakfast','06:00:00','11:00:00',0,1,1),(2,'Lunch','12:00:00','15:00:00',1,1,2),(3,'Dinner','19:00:00','23:30:00',1,1,3);
CREATE TABLE IF NOT EXISTS qr_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, issued_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, status TINYINT NOT NULL DEFAULT 1, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS meal_attendance (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, meal_type_id INT NOT NULL, meal_date DATE NOT NULL, scan_timestamp DATETIME NULL, qr_token_id BIGINT NULL, status ENUM('valid','void') NOT NULL DEFAULT 'valid', source ENUM('scan','manual','legacy') NOT NULL, legacy_id INT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY employee_day_meal(employee_id,meal_date,meal_type_id), INDEX report_date(meal_date,meal_type_id,status), CONSTRAINT mj_employee_fk FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE RESTRICT, CONSTRAINT mj_meal_fk FOREIGN KEY(meal_type_id) REFERENCES meal_types(id) ON DELETE RESTRICT, CONSTRAINT mj_token_fk FOREIGN KEY(qr_token_id) REFERENCES qr_tokens(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO system_settings VALUES ('company_name','Medico Junction'),('timezone','Asia/Kolkata'),('qr_ttl','60'),('logo','');
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, admin_id INT NULL, action VARCHAR(80) NOT NULL, old_value LONGTEXT NULL, new_value LONGTEXT NULL, reason VARCHAR(500) NOT NULL DEFAULT '', ip_address VARCHAR(45) NOT NULL, created_at DATETIME NOT NULL, INDEX(created_at), FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rate_limits (bucket_key CHAR(64) NOT NULL, bucket BIGINT NOT NULL, hits INT NOT NULL, PRIMARY KEY(bucket_key,bucket)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(80) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
